953	export async function listMembers(
954	  input: ListMembersInput,
955	): Promise<Page<MemberWithUser>> {
956	  const db = getDb();
957	  const sort = { sortColumn: members.createdAt, idColumn: members.id };
958	
959	  const filters = compact(
960	    orgPredicate(members.orgId, input.orgId),
961	    liveMemberPredicate(),
962	    input.role === undefined ? undefined : eq(members.role, input.role),
963	    input.status === undefined ? undefined : eq(members.status, input.status),
964	    input.query === undefined
965	      ? undefined
966	      : or(
967	          like(users.name, `%${input.query}%`),
968	          like(users.email, `%${input.query}%`),
969	        ),
970	  );
971	
972	  const total = db
973	    .select({ value: count() })
974	    .from(members)
975	    .innerJoin(users, eq(users.id, members.userId))
976	    .where(and(...filters))
977	    .get();
978	
979	  const rows = db
980	    .select({ member: members, user: users })
981	    .from(members)
982	    .innerJoin(users, eq(users.id, members.userId))
983	    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
984	    .orderBy(desc(members.createdAt), desc(members.id))
985	    .limit(probeLimit(input.limit))
986	    .all();
987	
988	  return toPage(
989	    rows,
990	    input.limit,
991	    total?.value ?? 0,
992	    (row) => ({ ...toMember(row.member), user: toUser(row.user) }),
993	    (row) => ({ id: row.member.id, sortValue: row.member.createdAt }),
994	  );
995	}
