301	/**
302	 * Role changes carry two rules the permission matrix cannot express:
303	 * nobody may grant a role above their own, and the last owner may not be
304	 * demoted. Both are checked after `can()` has had its say.
305	 */
306	export async function updateMemberRole(
307	  actor: Actor,
308	  input: UpdateMemberRoleInput,
309	): Promise<Member> {
310	  assertOrgScope(actor, input.orgId);
311	
312	  const member = requireFound(
313	    await memberRepo.findMemberById(input.orgId, input.memberId),
314	    "Member",
315	    input.memberId,
316	  );
317	  assertCan(actor, "member:update_role", memberResource(member));
318	
319	  if (!hasRoleAtLeast(actor.role, input.role)) {
320	    throw new Error(
321	      `A ${actor.role} cannot grant the ${input.role} role`,
322	    );
323	  }
324	
325	  await assertLastOwnerRetained(input.orgId, input.memberId, input.role);
326	
327	  const updated = await memberRepo.updateMemberRole(
328	    input.orgId,
329	    input.memberId,
330	    input.role,
331	  );
332	
333	  await emit("member.role_changed", {
334	    ...actorEnvelope(actor),
335	    memberId: updated.id,
336	    from: member.role,
337	    to: updated.role,
338	  });
339	
340	  return updated;
341	}
