391	 * it, and the invariant must not be stated twice.
392	 */
393	export async function assertLastOwnerRetained(
394	  orgId: OrgId,
395	  memberId: MemberId,
396	  nextRole: Role,
397	): Promise<void> {
398	  if (nextRole === "owner") return;
