403	export async function getBillingSummary(
404	  actor: Actor,
405	  orgId: OrgId,
406	): Promise<BillingSummary> {
407	  assertOrgScope(actor, orgId);
408	  assertCan(actor, "org:manage_billing", billingResource(orgId));
409	
410	  const subscription = requireFound(
411	    await subscriptionRepo.findSubscription(orgId),
412	    "Subscription",
413	    orgId,
414	  );
415	
416	  const checks = await Promise.all(
417	    SUMMARY_RESOURCES.map((resource) => checkLimit(orgId, resource, 0)),
418	  );
419	
420	  const limits = getPlanLimits(subscription.plan);
421	
422	  return {
423	    orgId,
424	    subscription,
425	    checks,
426	    upcomingInvoiceCents:
427	      limits.priceCentsPerSeatMonthly *
428	      subscription.seats *
429	      (subscription.interval === "annual" ? 12 : 1),
430	  };
431	}
