433	/**
434	 * The one place a quota is evaluated. Every guard elsewhere calls this rather
435	 * than reading `PLAN_LIMITS` itself, so a new plan dimension needs changing in
436	 * exactly two files: `plan-limits.ts` and `usageFor()` below.
437	 */
438	export async function checkLimit(
439	  orgId: OrgId,
440	  resource: LimitedResource,
441	  requested = 1,
442	): Promise<LimitCheck> {
443	  const plan = await planFor(orgId);
444	  const used = await usageFor(orgId, resource);
445	  const limit = getLimit(plan, resource);
446	
447	  return {
448	    resource,
449	    plan,
450	    limit,
451	    used,
452	    remaining: Math.max(0, limit - used),
453	    exceeded: wouldExceedLimit(plan, resource, used, requested),
454	  };
455	}
