457	/** Throwing form used by the create paths, and it emits the breach event. */
458	export async function assertWithinLimit(
459	  orgId: OrgId,
460	  resource: LimitedResource,
461	  requested = 1,
462	): Promise<void> {
463	  const check = await checkLimit(orgId, resource, requested);
464	  if (!check.exceeded) return;
465	
466	  await emit("billing.limit_exceeded", {
467	    orgId,
468	    actorId: null,
469	    occurredAt: toIsoTimestamp(new Date()),
470	    resource,
471	    limit: check.limit,
472	    used: check.used,
473	  });
474	
475	  throw new Error(
476	    `Plan ${check.plan} allows ${check.limit} ${resource}; ${check.used} are in use`,
477	  );
478	}
