482	 * alternative is silently breaking their workspace at the next write.
483	 */
484	export async function changePlan(
485	  actor: Actor,
486	  input: ChangePlanInput,
487	): Promise<Subscription> {
488	  assertOrgScope(actor, input.orgId);
489	  assertCan(actor, "org:manage_billing", billingResource(input.orgId));
490	
491	  const currentPlan = await planFor(input.orgId);
492	
493	  for (const resource of SUMMARY_RESOURCES) {
494	    const used = await usageFor(input.orgId, resource);
495	    if (wouldExceedLimit(input.plan, resource, used, 0)) {
496	      throw new Error(
