674	    );
675	    const channels = resolveChannels(preference, flags);
676	    if (channels.length === 0) continue;
677	
678	    rows.push({
679	      orgId,
680	      recipientId,
681	      kind,
682	      title: payload.title,
683	      body: payload.body,
684	      href: payload.href,
