/**
 * Ownership-handover offers, and the one transaction that moves the recorded
 * owner. Every read and write is filtered by `orgId`.
 */
import { and, desc, eq, isNull, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, members, organizations, ownershipHandovers } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { toOrganization } from "./_mappers";
import type { OwnershipHandoverRow } from "@/server/db";
import type { IsoTimestamp, MemberId, OrgId, UserId } from "@/types/common";
import type { Role } from "@/types/member";
import type {
  Organization,
  OwnershipHandover,
  OwnershipHandoverStatus,
} from "@/types/organization";

/** One role change applied by a transfer, in the order it was applied. */
export interface TransferRoleChange {
  readonly memberId: MemberId;
  readonly from: Role;
  readonly to: Role;
}

export interface OwnershipTransferResult {
  readonly organization: Organization;
  readonly handover: OwnershipHandover;
  readonly roleChanges: readonly TransferRoleChange[];
}

function toHandover(row: OwnershipHandoverRow): OwnershipHandover {
  return {
    id: row.id,
    orgId: row.orgId as OrgId,
    fromUserId: row.fromUserId as UserId,
    toUserId: row.toUserId as UserId,
    status: row.status,
    expiresAt: row.expiresAt as IsoTimestamp,
    createdAt: row.createdAt as IsoTimestamp,
    resolvedAt: row.resolvedAt === null ? null : (row.resolvedAt as IsoTimestamp),
  };
}

/**
 * The org's unresolved offer, if any. It may already be past `expiresAt` —
 * deciding whether it still counts as open is the service's job.
 */
export async function findPendingHandover(
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .orderBy(desc(ownershipHandovers.createdAt), desc(ownershipHandovers.id))
    .limit(1)
    .get();
  return row ? toHandover(row) : null;
}

export async function insertHandover(
  orgId: OrgId,
  fromUserId: UserId,
  toUserId: UserId,
  createdAt: IsoTimestamp,
  expiresAt: IsoTimestamp,
): Promise<OwnershipHandover> {
  const row = getDb()
    .insert(ownershipHandovers)
    .values({
      id: newId(),
      orgId,
      fromUserId,
      toUserId,
      status: "pending",
      expiresAt,
      resolvedAt: null,
      createdAt,
      updatedAt: createdAt,
    })
    .returning()
    .get();
  return toHandover(row);
}

/** Moves a pending offer to a terminal status. */
export async function resolveHandover(
  orgId: OrgId,
  handoverId: string,
  status: Exclude<OwnershipHandoverStatus, "pending">,
  resolvedAt: IsoTimestamp | null,
  at: IsoTimestamp,
): Promise<OwnershipHandover> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt, updatedAt: at })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.id, handoverId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .returning()
    .get();

  if (!row) {
    throw new Error(`Ownership handover ${handoverId} is not pending in org ${orgId}`);
  }
  return toHandover(row);
}

/** Withdraws every pending offer the user made or received in this org. */
export async function cancelHandoversInvolving(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(ownershipHandovers)
    .set({ status: "canceled", resolvedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        or(
          eq(ownershipHandovers.fromUserId, userId),
          eq(ownershipHandovers.toUserId, userId),
        ),
      ),
    )
    .run();
}

/**
 * Applies an accepted offer atomically: the new owner is promoted first, the
 * recorded owner is switched, and only then does the previous owner step down
 * to admin — so the org holds an owner at every step. Returns `null` when the
 * offer is no longer pending or the accepting member is gone.
 */
export async function applyOwnershipTransfer(
  orgId: OrgId,
  handoverId: string,
  at: IsoTimestamp,
): Promise<OwnershipTransferResult | null> {
  return getDb().transaction((tx) => {
    const offer = tx
      .select()
      .from(ownershipHandovers)
      .where(
        and(
          orgPredicate(ownershipHandovers.orgId, orgId),
          eq(ownershipHandovers.id, handoverId),
          eq(ownershipHandovers.status, "pending"),
        ),
      )
      .get();
    if (!offer) return null;

    const liveMember = (userId: string) =>
      tx
        .select()
        .from(members)
        .where(
          and(
            orgPredicate(members.orgId, orgId),
            eq(members.userId, userId),
            isNull(members.archivedAt),
          ),
        )
        .get();

    const incoming = liveMember(offer.toUserId);
    if (!incoming) return null;

    const roleChanges: TransferRoleChange[] = [];

    if (incoming.role !== "owner") {
      tx.update(members)
        .set({ role: "owner", updatedAt: at })
        .where(and(orgPredicate(members.orgId, orgId), eq(members.id, incoming.id)))
        .run();
      roleChanges.push({
        memberId: incoming.id as MemberId,
        from: incoming.role,
        to: "owner",
      });
    }

    const orgRow = tx
      .update(organizations)
      .set({ ownerId: offer.toUserId, updatedAt: at })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();
    if (!orgRow) throw new Error(`Organization ${orgId} not found`);

    const outgoing = liveMember(offer.fromUserId);
    if (outgoing && outgoing.id !== incoming.id && outgoing.role === "owner") {
      tx.update(members)
        .set({ role: "admin", updatedAt: at })
        .where(and(orgPredicate(members.orgId, orgId), eq(members.id, outgoing.id)))
        .run();
      roleChanges.push({
        memberId: outgoing.id as MemberId,
        from: "owner",
        to: "admin",
      });
    }

    const resolved = tx
      .update(ownershipHandovers)
      .set({ status: "accepted", resolvedAt: at, updatedAt: at })
      .where(eq(ownershipHandovers.id, offer.id))
      .returning()
      .get();

    return {
      organization: toOrganization(orgRow),
      handover: toHandover(resolved),
      roleChanges,
    };
  });
}

