open(p,'a').write('''
/**
 * The recorded owner offers the workspace to another active member. Nothing
 * changes hands until the offered member accepts; at most one offer is open.
 */
export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  assertRecordedOwner(actor, org);

  if (toUserId === org.ownerId) throw new OwnershipHandoverError("self");

  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const now = new Date();
  const pending = await loadPendingOffer(org, now);
  if (pending?.open === true) throw new OwnershipHandoverError("pending_exists");
  if (pending) {
    // A lapsed offer is closed for good once a new one replaces it.
    await handoverRepo.resolveHandover(
      orgId,
      pending.offer.id,
      "expired",
      null,
      toIsoTimestamp(now),
    );
  }

  const offer = await handoverRepo.insertHandover(
    orgId,
    org.ownerId,
    toUserId,
    toIsoTimestamp(now),
    toIsoTimestamp(new Date(now.getTime() + HANDOVER_TTL_MS)),
  );

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "You were offered ownership of a workspace",
    body: `Accept to become the owner of ${org.name}`,
    href: "/settings/members",
    actorId: actor.userId,
  });

  return offer;
}

/**
 * The offered member takes the workspace over: they become the recorded owner
 * with the owner role, and the previous owner steps down to admin. The swap
 * is one transaction that promotes before it demotes, so the last-owner
 * invariant holds throughout and is deliberately not consulted here.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const offer = await requireOfferFor(actor, orgId);

  const result = await handoverRepo.applyOwnershipTransfer(
    orgId,
    offer.id,
    toIsoTimestamp(new Date()),
  );
  if (!result) throw new OwnershipHandoverError("nothing_pending");

  for (const change of result.roleChanges) {
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: change.memberId,
      from: change.from,
      to: change.to,
    });
  }

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: offer.fromUserId,
    toUserId: offer.toUserId,
  });

  return result.organization;
}

export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const offer = await requireOfferFor(actor, orgId);

  const at = toIsoTimestamp(new Date());
  return handoverRepo.resolveHandover(orgId, offer.id, "declined", at, at);
}

/** The recorded owner withdraws the open offer. */
export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  assertRecordedOwner(actor, org);

  const pending = await loadPendingOffer(org, new Date());
  if (pending?.open !== true) throw new OwnershipHandoverError("nothing_pending");

  const at = toIsoTimestamp(new Date());
  return handoverRepo.resolveHandover(orgId, pending.offer.id, "canceled", at, at);
}

/** The open offer, visible to every member of the workspace; `null` if none. */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  const pending = await loadPendingOffer(org, new Date());
  return pending?.open === true ? pending.offer : null;
}

/**
 * Offering and withdrawing belong to the recorded owner alone. The owner
 * *role* is not enough — a second owner-role member is refused — so this is
 * decided on `org.ownerId` and reported as a denial of
 * `org:transfer_ownership`.
 */
function assertRecordedOwner(actor: Actor, org: Organization): void {
  assertOrgScope(actor, org.id);
  if (actor.userId === org.ownerId) return;

  throw new PermissionDeniedError("org:transfer_ownership", {
    allowed: false,
    action: "org:transfer_ownership",
    resourceKind: "organization",
    reason: "denied_by_role",
  });
}

/**
 * The org's unresolved offer and whether it can still be acted on. An offer
 * made at T is open before T + 7 days and lapsed from that instant on. An
 * unlapsed offer whose sides no longer stand — either one has left, or the
 * offerer is no longer the recorded owner — is withdrawn here and reported as
 * absent.
 */
async function loadPendingOffer(
  org: Organization,
  now: Date,
): Promise<{ offer: OwnershipHandover; open: boolean } | null> {
  const offer = await handoverRepo.findPendingHandover(org.id);
  if (!offer) return null;

  if (now.getTime() >= new Date(offer.expiresAt).getTime()) {
    return { offer, open: false };
  }

  const from = await memberRepo.findMember(org.id, offer.fromUserId);
  const to = await memberRepo.findMember(org.id, offer.toUserId);
  const stillStands =
    offer.fromUserId === org.ownerId &&
    from?.status === "active" &&
    to?.status === "active";

  if (!stillStands) {
    const at = toIsoTimestamp(now);
    await handoverRepo.resolveHandover(org.id, offer.id, "canceled", at, at);
    return null;
  }

  return { offer, open: true };
}

/**
 * The open offer addressed to `actor`, for accept and decline. Anyone but the
 * offered member sees nothing pending; the offered member is told when their
 * offer has lapsed.
 */
async function requireOfferFor(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  const pending = await loadPendingOffer(org, new Date());

  if (!pending || pending.offer.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (!pending.open) throw new OwnershipHandoverError("expired");

  return pending.offer;
}
''')
